[
  {
    "statement": "Several non-lethal strategies are available for managing human-primate conflict.",
    "citations": []
  },
  {
    "statement": "The evidence for the effectiveness of non-lethal strategies for managing human-primate conflict varies.",
    "citations": []
  },
  {
    "statement": "Installing mechanical barriers such as fences and ditches can be used to deter primates from entering agricultural areas.",
    "citations": [
      "1436"
    ]
  },
  {
    "statement": "Using loud-speakers to broadcast primate alarm calls is a sound-based deterrent.",
    "citations": [
      "1447"
    ]
  },
  {
    "statement": "Broadcasting sounds of potential threats like barking dogs, explosions, or gunshots can be used as a sound-based deterrent.",
    "citations": [
      "1446"
    ]
  },
  {
    "statement": "Using loud noises from banger sticks, drums, tins, and iron sheets is an acoustic method to deter crop damage by mammals.",
    "citations": [
      "2460"
    ]
  },
  {
    "statement": "Studies show that loud noises activated when animals are in the vicinity can reduce or partially reduce crop damage by various species, including elephants.",
    "citations": [
      "2460"
    ]
  },
  {
    "statement": "Target species distress calls or signals have been tested as a deterrent, with mixed results.",
    "citations": [
      "2488"
    ]
  },
  {
    "statement": "Some studies found that certain mammals like white-tailed deer and Asian elephants were deterred by their own species' distress calls.",
    "citations": [
      "2488"
    ]
  },
  {
    "statement": "Other studies found that target species distress calls had no deterrent effect.",
    "citations": [
      "2488"
    ]
  },
  {
    "statement": "Chemical deterrents include using chili-based methods such as chili-spray, chili smoke, chili fences and chili extract in projectiles.",
    "citations": [
      "2492"
    ]
  },
  {
    "statement": "Studies show that chili-based methods can repel elephants at least initially.",
    "citations": [
      "2492"
    ]
  },
  {
    "statement": "Some studies found chili smoke and chili fences to be ineffective deterrents.",
    "citations": [
      "2492"
    ]
  },
  {
    "statement": "A human intervention method involves humans chasing primates using bright light.",
    "citations": [
      "1450"
    ]
  },
  {
    "statement": "Removing human food waste that may serve as food sources for primates is a management strategy to avoid disease transmission and conflict.",
    "citations": [
      "1561"
    ]
  },
  {
    "statement": "Planting crops favoured by primates away from primate areas is a management strategy.",
    "citations": [
      "1440"
    ]
  },
  {
    "statement": "Discouraging the planting of fruit trees and vegetable gardens on urban edges is a management strategy.",
    "citations": [
      "1424"
    ]
  },
  {
    "statement": "Implementing speed limits in areas with high primate densities is a management strategy to reduce vehicle collisions.",
    "citations": [
      "1458"
    ]
  },
  {
    "statement": "Translocation of crop-raiding animals away from crops is another option for managing conflict.",
    "citations": [
      "2485"
    ]
  },
  {
    "statement": "Studies suggest that the translocation of crop-raiding animals may have negative impacts on the animals' survival rates.",
    "citations": [
      "2485"
    ]
  }
]

